#pragma once
void vp_city_happiness_tests(){
    using namespace civ5::runtime;using namespace civ5::saves;
    constexpr auto vp=TechnologyProfile::vp542;
    RulesDatabase db;db.apply_sql("CREATE TABLE Defines(Name,Value);INSERT INTO Defines VALUES('DEFAULT_SPECIALIST',0),('CITY_STRENGTH_THRESHOLD_FOR_BONUSES',10),('UNHAPPINESS_PER_SPECIALIST',150),('AI_HANDICAP',7);CREATE TABLE Yields(ID,Type);INSERT INTO Yields VALUES(4,'YIELD_CULTURE'),(6,'YIELD_TOURISM'),(12,'YIELD_JFD_CRIME');CREATE TABLE HandicapInfos(ID,Type,HappinessDefaultCapital,AIHappinessDefaultCapital);INSERT INTO HandicapInfos VALUES(2,'PLAYER',3,4),(7,'AI',5,6);CREATE TABLE Policies(ID,Type,IsDummy);INSERT INTO Policies VALUES(0,'REAL',0),(1,'DUMMY',1),(2,'FREE',0),(3,'FINISHER',0);CREATE TABLE GameOptions(Type,\"Default\");INSERT INTO GameOptions VALUES('GAMEOPTION_ONE_CITY_CHALLENGE',0);");
    auto types=db.cache_info_types();auto defines=db.cache_global_defines(GlobalDefineProfile::vp542);auto rules=load_vp_city_happiness_rules(db,types);
    check(rules.handicaps.at(7).ai_capital==6&&rules.dummy_policies.at(1)&&rules.culture==4&&rules.crime==12,"Happiness rules bind handicap, policy dummy and yield identities");
    CustomModOptions options;options.entries["BALANCE_VP"].value=1;
    ResearchContext setup;setup.profile=vp;setup.game_handicap=7;auto &sp=setup.players[5];sp.slot_status=3;sp.handicap=2;sp.policies_resolved=true;sp.policies={0,1,2,3};
    CityYieldContext world;world.profile=vp;world.turn_slice=1;auto &p=world.players[5];p.capital=42;p.civilization=0;auto &great_work_profile=ensure_vp_great_work_profile(world);great_work_profile.players[5]={};auto &happiness_profile=ensure_vp_city_happiness_profile(world);happiness_profile.players[5]={};happiness_profile.trade_stats[5]={};
    auto &food_profile=ensure_vp_city_food_profile(world);food_profile.players[5]={};
    auto &city=p.cities[42];city.owner=5;city.id=42;city.population=10;city.building_counts_resolved=true;happiness_profile.cities[{5,42}]={};great_work_profile.cities[{5,42}]={};auto &city_plot=ensure_vp_city_plot_profile_city(world,5,42).yields.emplace();
    food_profile.cities[{5,42}].specialists={{0,99},{1,3},{2,2}};city_plot.strength=1000;city_plot.garrison=8;
    auto &a=happiness_profile.cities[{5,42}];auto &h=happiness_profile.players[5];
    SavedMapProjection map{{1,1}};PlotPassability pass;PlotWaterRules wr;wr.profile=vp;PlotWaterState ws;ws.layout=GameStateLayout::vp542_corpus;
    PlotWaterContext water{map,ws,wr,types,pass,setup,world,defines,&options};VpPlotReligionRules rr;VpPlotReligionContext religion{rr,water};
    VpGreatWorkRules gr;gr.buildings[10].yield=4;CityYieldRules cr;cr.profile=vp;cr.civilization_buildings[0][1]=10;cr.civilization_buildings[0][2]=-1;
    struct Services:VpGreatWorkServices{void unlock_capital_theming_achievement(std::int64_t)override{throw std::runtime_error("Unexpected happiness achievement");}} services;
    VpGreatWorkContext great{world,cr,gr,religion,services};std::map<std::int64_t,std::int64_t> eras;VpCityFoodRules fr;fr.specialist_slots=3;VpCityFoodContext food{world,setup,eras,fr,defines};
    MaintenanceContext units;units.profile=vp;units.players[5].units[8]={};units.players[5].units[9]={};VpCityHappinessContext c{rules,great,food,units,setup,db};
    great_work_profile.cities[{5,42}].works={{1,0,-1},{1,0,-1},{1,99,999},{2,0,0}};
    check(vp_city_great_works(great,city)==3&&vp_city_great_works(great,city,false)==3,"Work count keeps duplicate slots and unresolved work IDs, excluding absent building Info");
    gr.buildings[10].yield=-1;check(vp_city_great_works(great,city)==3&&vp_city_great_works(great,city,false)==0,"Default great-work count includes buildings with no yield");gr.buildings[10].yield=4;
    check(vp_total_specialists(food,city)==5,"Shared specialist total excludes default workers");city.population=1;check(vp_total_specialists(food,city)==5,"Specialist count is not capped at population");city.population=10;
    h.garrison=2;h.strength=3;h.per_x_works=2;h.per_population=YieldFraction(1,3);h.policy_capital=4;h.per_policy_from_policies=YieldFraction(1,2);h.per_policy=YieldFraction(1,2);h.specialists=4;h.policy_city=-2;h.per_city=3;h.per_x_population=3;h.per_route=2;
    TradeRouteObservation route;route.origin_x=route.origin_y=route.destination_x=route.destination_y=-1;auto &route_profile=ensure_vp_trade_route(route);route_profile.origin_id=42;route_profile.destination_id=43;route.origin_owner=5;route.destination_owner=6;world.players[6].minor=true;world.trade_routes={route,route};
    auto q=vp_city_policy_happiness(c,city);check(q.garrison==2&&q.strength==3&&q.great_works==1&&q.population_global==3&&q.capital==4&&q.policies_from_policies==1&&q.policies==1&&q.specialists==6&&q.per_city==1&&q.population==3&&q.trade==4&&q.total==29,"All policy happiness branches retain separate truncation and dummy-policy exclusion");
    a.empire=7;a.buildings=8;a.building_classes=-2;a.religion=3;a.unmodded_buildings=-1;
    auto z=vp_city_local_happiness(c,city);check(z.total==47&&z.handicap==3&&!z.suppressed,"Local happiness sums all saved contributions without a population cap");
    check(vp_city_local_happiness(c,city,0,true).total==40,"Empire contribution can be excluded independently");
    check(vp_city_policy_happiness(c,city,-11).population==0&&vp_city_policy_happiness(c,city,-14).population==-1&&vp_city_policy_happiness(c,city,-14).population_global==0,"Hypothetical population truncates signed per-X and gates positive fractional contribution");
    a.policies[4]=-2;h.to_culture=25;auto y=vp_city_policy_yield(c,city,4);check(y.base==-200&&y.happiness==1175&&y.total_times100==975,"Policy culture adds happiness in hundredths without an extra percent division");
    check(vp_city_policy_yield(c,city,6).total_times100==0,"Happiness conversion applies only to culture");
    city.puppet=true;check(vp_city_local_happiness(c,city).suppressed&&vp_city_policy_yield(c,city,4).total_times100==-200,"Annexable puppet suppresses happiness but keeps raw policy income");
    h.no_annexing=true;check(!vp_city_local_happiness(c,city).suppressed&&vp_city_policy_happiness(c,city).population==0,"No-annexing trait exempts puppet suppression, but not per-X population gate");a.occupied=true;check(!vp_city_local_happiness(c,city).suppressed,"Puppet is never treated as occupied, including no-annexing cities");a.occupied=false;city.puppet=false;
    city.razing=true;check(vp_city_local_happiness(c,city).suppressed,"Razing suppresses VP happiness");city.razing=false;
    city.resistance=true;check(vp_city_local_happiness(c,city).suppressed,"Resistance suppresses VP happiness");city.resistance=false;
    a.occupied=true;a.no_occupied_unhappiness=-1;check(vp_city_local_happiness(c,city).suppressed,"Occupation immunity count must be positive");a.no_occupied_unhappiness=1;check(!vp_city_local_happiness(c,city).suppressed,"Positive occupation immunity restores happiness");a.occupied=false;
    options.entries["BALANCE_VP"].value=0;p.capital=99;city.razing=true;check(!vp_city_local_happiness(c,city).suppressed&&vp_city_policy_happiness(c,city).population_global==0,"CP keeps happiness in disrupted cities and limits global population bonus to capital");
    p.capital=42;check(vp_city_policy_happiness(c,city).population_global==3&&vp_city_policy_yield(c,city,4).total_times100==-200,"CP capital gets population bonus without VP culture conversion");city.razing=false;options.entries["BALANCE_VP"].value=1;
    setup.game_options={{"GAMEOPTION_ONE_CITY_CHALLENGE",2}};check(vp_city_local_happiness(c,city).handicap==3,"Game option requires exactly one");setup.game_options={{"GAMEOPTION_ONE_CITY_CHALLENGE",1}};check(vp_city_local_happiness(c,city).handicap==6,"One-city challenge doubles human capital default");
    options.entries["HUMAN_USES_AI_HANDICAP"].value=1;check(vp_city_local_happiness(c,city).handicap==10,"One-city challenge uses AI handicap while human mechanics remain enabled");
    options.entries["HUMAN_USES_AI_MECHANICS"].value=1;check(vp_city_local_happiness(c,city).handicap==11,"AI mechanics disables challenge doubling and adds game AI capital bonus");
    options.entries["HUMAN_USES_AI_HANDICAP"].value=0;check(vp_city_local_happiness(c,city).handicap==3,"AI mechanics alone retains human handicap branch");sp.slot_status=1;check(vp_city_local_happiness(c,city).handicap==9,"AI player combines its own handicap and game AI bonus");sp.slot_status=3;
    sp.handicap=999;check(vp_city_local_happiness(c,city).handicap==0,"Absent handicap follows source empty Info defaults");sp.handicap=2;
    options.entries["BALANCE_CORE_JFD"].value=1;a.crime[12]=-3;a.development[12]=2;a.development[6]=999;z=vp_city_local_happiness(c,city);check(z.crime==-3&&z.development==2,"Both JFD happiness terms use crime yield identity");
    a.empire=-1000;h.to_culture=-25;y=vp_city_policy_yield(c,city,4);check(y.happiness>0,"Negative happiness times negative conversion remains positive");h.to_culture=25;check(vp_city_policy_yield(c,city,4).happiness==0,"Only final converted happiness is clamped at zero");a.empire=7;
    h.per_x_works=-2;check(vp_city_policy_happiness(c,city).great_works==-1,"Negative nonzero great-work divisor is preserved");h.per_x_works=2;
    h.per_population=YieldFraction(-1,2);h.per_policy=YieldFraction(-1,2);check(vp_city_policy_happiness(c,city).population_global==0&&vp_city_policy_happiness(c,city).policies==0,"Negative fractional bonuses are gated");
    city_plot.garrison_override=9;check(vp_city_garrison(world,units,city)==&units.players.at(5).units.at(9),"Valid garrison override wins with a saved garrison ID");
    city_plot.garrison=-1;check(!vp_city_garrison(world,units,city),"Override alone does not make HasGarrison true");city_plot.garrison=8;city_plot.garrison_override=99;
    check(vp_city_garrison(world,units,city)==&units.players.at(5).units.at(8),"Missing override falls back to saved garrison");city_plot.garrison=100;check(!vp_city_garrison(world,units,city)&&city_plot.garrison==-1,"Missing garrison clears shared saved ID");
    h.garrison=0;city_plot.garrison=100;vp_city_policy_happiness(c,city);check(city_plot.garrison==100,"Inactive garrison policy leaves stale reference untouched");
    city_plot.strength=999;check(vp_city_policy_happiness(c,city).strength==0,"Strength threshold uses stored hundredths");
    auto &s=happiness_profile.trade_stats[5];check(s.minors==2&&s.international_out==2&&s.from_city.at(42)==2,"Trade cache counts duplicate outgoing minor routes");
    world.trade_routes.clear();check(vp_trade_routes_from_city(world,5,&city)==2,"Same-slice cache stays valid after raw route changes");world.turn_slice=2;check(vp_trade_routes_from_city(world,5,&city)==0&&s.from_city.contains(42),"Next slice rebuilds and missing city lookup inserts zero");
    route.origin_owner=5;route.destination_owner=5;world.trade_routes={route};route.origin_owner=6;route.destination_owner=5;world.trade_routes.push_back(route);route_profile.origin_id=-1;world.trade_routes.push_back(route);
    world.turn_slice=3;vp_update_trade_stats(world,5);check(s.internal==1&&s.international_in==1&&s.international_out==0&&s.to_city.at(43)==2,"Route validity uses IDs and owners even when all coordinates are minus one");
    vp_reset_trade_stats(world,5);world.turn_slice=0;vp_update_trade_stats(world,5);check(s.internal==0&&s.turn_slice==0,"Explicit native reset produces a slice-zero cache hit");
    s.turn_slice.reset();vp_update_trade_stats(world,5);check(s.internal==1,"Unresolved imported cache rebuilds even at slice zero");
    check(vp_trade_routes_from_city(world,999,nullptr)==0,"Null-city route query returns before player lookup");
    constexpr std::int64_t big=4294967300LL;city.population=big;h.per_population=YieldFraction(1,2);h.per_city=big;h.strength=big;city_plot.strength=big;
    q=vp_city_policy_happiness(c,city);check(q.per_city==big-2&&q.population_global==big/2&&q.strength==big&&q.total>big*2,"Population, modifiers and happiness totals exceed 32-bit range");
    h.per_city=INT64_MAX;rejects([&]{vp_city_local_happiness(c,city);});h.per_city=0;
    auto detached=city;rejects([&]{vp_city_local_happiness(c,detached);});rejects([&]{vp_city_policy_yield(c,city,999);});
    happiness_profile.players.erase(5);rejects([&]{vp_city_local_happiness(c,city);});
}
